 58→func runAttach(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, force bool) error {
 59→	logCtx := logging.WithComponent(ctx, "attach")
 60→
 61→	// Validate session ID format
 62→	if err := validation.ValidateSessionID(sessionID); err != nil {
 63→		return fmt.Errorf("invalid session ID: %w", err)
 64→	}
 65→
 66→	// Ensure we're in a git repo
 67→	repoRoot, err := paths.WorktreeRoot(ctx)
 68→	if err != nil {
 69→		return fmt.Errorf("not a git repository: %w", err)
 70→	}
 71→
 72→	// Check session isn't already tracked
 73→	store, err := session.NewStateStore(ctx)
 74→	if err != nil {
 75→		return fmt.Errorf("failed to open session store: %w", err)
 76→	}
 77→	existing, err := store.Load(ctx, sessionID)
 78→	if err != nil {
 79→		return fmt.Errorf("failed to check existing session: %w", err)
 80→	}
 81→	if existing != nil {
 82→		return fmt.Errorf("session %s is already tracked by Entire", sessionID)
 83→	}
 84→
 85→	// Resolve agent and transcript path
 86→	ag, err := agent.Get(agentName)
 87→	if err != nil {
 88→		return fmt.Errorf("agent %q not available: %w", agentName, err)
 89→	}
 90→	agentType := ag.Type()
 91→
 92→	transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
 93→	if err != nil {
 94→		return fmt.Errorf("failed to resolve transcript path: %w", err)
 95→	}
 96→	// Claude Code uses cwd (not repo root) for its project directory, so if the
 97→	// session was started from a subdirectory, the repo-root-based path won't exist.
 98→	// Search across all project directories that are subdirectories of the repo.
 99→	if _, statErr := os.Stat(transcriptPath); os.IsNotExist(statErr) {
100→		if found, searchErr := searchTranscriptInSubdirs(ctx, sessionID, ag); searchErr == nil {
101→			transcriptPath = found
102→		}
103→	}
104→	if _, statErr := os.Stat(transcriptPath); os.IsNotExist(statErr) {
105→		return fmt.Errorf("transcript not found at %s\nIs the session ID correct?", transcriptPath)
106→	}
107→
108→	// Read transcript data
109→	transcriptData, err := ag.ReadTranscript(transcriptPath)
110→	if err != nil {
111→		return fmt.Errorf("failed to read transcript: %w", err)
112→	}
113→
114→	// Extract modified files from transcript
115→	var modifiedFiles []string
116→	if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
117→		if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptPath, 0); fileErr != nil {
118→			logging.Warn(logCtx, "failed to extract modified files from transcript")
119→		} else {
120→			modifiedFiles = files
121→		}
122→	}
123→
124→	// Detect file changes via git status (no pre-untracked filter since we don't know pre-state)
125→	changes, err := DetectFileChanges(ctx, nil)
126→	if err != nil {
127→		logging.Warn(logCtx, "failed to detect file changes")
128→	}
129→
130→	// Filter and normalize paths
131→	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
132→	var relNewFiles, relDeletedFiles []string
133→	if changes != nil {
134→		relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
135→		relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
136→		relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(changes.Modified, repoRoot))
137→	}
138→
139→	// Filter to uncommitted files only
140→	relModifiedFiles = filterToUncommittedFiles(ctx, relModifiedFiles, repoRoot)
141→
142→	// Ensure strategy setup
143→	if err := strategy.EnsureSetup(ctx); err != nil {
144→		logging.Warn(logCtx, "failed to ensure strategy setup")
145→	}
146→
147→	// Create session metadata directory and copy transcript
148→	sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
149→	sessionDirAbs, err := paths.AbsPath(ctx, sessionDir)
150→	if err != nil {
151→		sessionDirAbs = sessionDir
152→	}
153→	if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
154→		return fmt.Errorf("failed to create session directory: %w", err)
155→	}
156→	logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
157→	if err := os.WriteFile(logFile, transcriptData, 0o600); err != nil {
158→		return fmt.Errorf("failed to write transcript: %w", err)
159→	}
160→
161→	// Get git author
162→	author, err := GetGitAuthor(ctx)
163→	if err != nil {
164→		return fmt.Errorf("failed to get git author: %w", err)
165→	}
166→
167→	// Extract first prompt from transcript for the commit message
168→	firstPrompt := extractFirstPromptFromTranscript(transcriptData)
169→	commitMessage := generateCommitMessage(firstPrompt, agentType)
170→
171→	// Initialize session state BEFORE SaveStep so it exists when SaveStep loads it
172→	strat := GetStrategy(ctx)
173→	if err := strat.InitializeSession(ctx, sessionID, agentType, transcriptPath, firstPrompt, ""); err != nil {
174→		return fmt.Errorf("failed to initialize session: %w", err)
175→	}
176→
177→	// Update the session state with attach-specific metadata
178→	state, err := strategy.LoadSessionState(ctx, sessionID)
179→	if err != nil {
180→		return fmt.Errorf("failed to load session state: %w", err)
181→	}
182→	if state != nil {
183→		state.CLIVersion = versioninfo.Version
184→		state.TranscriptPath = transcriptPath
185→		if err := strategy.SaveSessionState(ctx, state); err != nil {
186→			return fmt.Errorf("failed to save session state: %w", err)
187→		}
188→	}
189→
190→	// Build step context and save checkpoint
191→	totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
192→
193→	stepCtx := strategy.StepContext{
194→		SessionID:      sessionID,
195→		ModifiedFiles:  relModifiedFiles,
196→		NewFiles:       relNewFiles,
197→		DeletedFiles:   relDeletedFiles,
198→		MetadataDir:    sessionDir,
199→		MetadataDirAbs: sessionDirAbs,
200→		CommitMessage:  commitMessage,
201→		TranscriptPath: transcriptPath,
202→		AuthorName:     author.Name,
203→		AuthorEmail:    author.Email,
204→		AgentType:      agentType,
205→	}
206→
207→	if err := strat.SaveStep(ctx, stepCtx); err != nil {
208→		return fmt.Errorf("failed to save checkpoint: %w", err)
209→	}
210→
211→	checkpointIDStr := condenseAndFinalizeSession(logCtx, strat, sessionID)
212→
213→	// Print confirmation
214→	fmt.Fprintf(w, "Attached session %s\n", sessionID)
215→	if totalChanges > 0 {
216→		fmt.Fprintf(w, "  Checkpoint saved with %d file(s)\n", totalChanges)
217→	} else {
218→		fmt.Fprintln(w, "  Checkpoint saved (transcript only, no uncommitted file changes detected)")
219→	}
220→	fmt.Fprintln(w, "  Session is now tracked — future prompts will be captured automatically")
221→
222→	// Offer to amend the last commit with the checkpoint trailer
223→	if checkpointIDStr != "" {
224→		if err := promptAmendCommit(ctx, w, checkpointIDStr, force); err != nil {
225→			logging.Warn(logCtx, "failed to amend commit", "error", err)
226→			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
227→		}
228→	}
229→
230→	return nil
231→}
