320→// extractFirstPromptFromTranscript reads transcript bytes and returns the first user prompt.
321→func extractFirstPromptFromTranscript(data []byte) string {
322→	lines, err := transcript.ParseFromBytes(data)
323→	if err != nil {
324→		return ""
325→	}
326→	for _, line := range lines {
327→		if line.Type == "user" {
328→			prompt := extractTextFromMessage(line.Message)
329→			if prompt != "" {
330→				return prompt
331→			}
332→		}
333→	}
334→	return ""
335→}
336→
337→// extractTextFromMessage extracts the text content from a transcript message.
338→func extractTextFromMessage(msg json.RawMessage) string {
339→	// Try string content first (simple user messages)
340→	var simple struct {
341→		Content string `json:"content"`
342→	}
343→	if err := json.Unmarshal(msg, &simple); err == nil && simple.Content != "" {
344→		return simple.Content
345→	}
346→
347→	// Try array content (messages with tool results, text blocks, etc.)
348→	var array struct {
349→		Content []struct {
350→			Type string `json:"type"`
351→			Text string `json:"text"`
352→		} `json:"content"`
353→	}
354→	if err := json.Unmarshal(msg, &array); err == nil {
355→		for _, block := range array.Content {
356→			if block.Type == "text" && block.Text != "" {
357→				return block.Text
358→			}
359→		}
360→	}
361→
362→	return ""
363→}
