 18→// Transcript message type constants - aliases to transcript package for local use.
 19→const (
 20→	transcriptTypeUser = transcript.TypeUser
 21→)
 22→
 23→// resolveTranscriptPath determines the correct file path for an agent's session transcript.
 24→// Computes the path dynamically from the current repo location for cross-machine portability.
 25→func resolveTranscriptPath(ctx context.Context, sessionID string, agent agentpkg.Agent) (string, error) {
 26→	repoRoot, err := paths.WorktreeRoot(ctx)
 27→	if err != nil {
 28→		return "", fmt.Errorf("failed to get worktree root: %w", err)
 29→	}
 30→
 31→	sessionDir, err := agent.GetSessionDir(repoRoot)
 32→	if err != nil {
 33→		return "", fmt.Errorf("failed to get agent session directory: %w", err)
 34→	}
 35→	return agent.ResolveSessionFile(sessionDir, sessionID), nil
 36→}
 37→
 38→// searchTranscriptInSubdirs searches for a session transcript across all Claude project
 39→// directories that correspond to subdirectories of the repo root. Claude Code uses cwd
 40→// (not repo root) for its project directory, so sessions started from subdirectories
 41→// are stored under different project directory names.
 42→func searchTranscriptInSubdirs(ctx context.Context, sessionID string, agent agentpkg.Agent) (string, error) {
 43→	repoRoot, err := paths.WorktreeRoot(ctx)
 44→	if err != nil {
 45→		return "", fmt.Errorf("failed to get worktree root: %w", err)
 46→	}
 47→
 48→	homeDir, err := os.UserHomeDir()
 49→	if err != nil {
 50→		return "", fmt.Errorf("failed to get home directory: %w", err)
 51→	}
 52→
 53→	projectsDir := filepath.Join(homeDir, ".claude", "projects")
 54→	entries, err := os.ReadDir(projectsDir)
 55→	if err != nil {
 56→		return "", fmt.Errorf("failed to read projects directory: %w", err)
 57→	}
 58→
 59→	// The repo root sanitized is the prefix for all matching project dirs.
 60→	// e.g. repo at /Users/username/cli → prefix "-Users-username-cli"
 61→	// Session started from /Users/username/cli/cmd → dir "-Users-username-cli-cmd"
 62→	repoPrefix := sanitizePathForSearch(repoRoot)
 63→
 64→	for _, entry := range entries {
 65→		if !entry.IsDir() {
 66→			continue
 67→		}
 68→		name := entry.Name()
 69→		// Must start with the repo prefix and either be exactly the prefix
 70→		// (already checked by resolveTranscriptPath) or be a subdirectory of it.
 71→		if name == repoPrefix || !hasPathPrefix(name, repoPrefix) {
 72→			continue
 73→		}
 74→		candidate := agent.ResolveSessionFile(filepath.Join(projectsDir, name), sessionID)
 75→		if _, statErr := os.Stat(candidate); statErr == nil {
 76→			return candidate, nil
 77→		}
 78→	}
 79→
 80→	return "", errors.New("transcript not found in any subdirectory project dir")
 81→}
 82→
 83→// sanitizePathForSearch converts a path the same way Claude Code does for project directories.
 84→func sanitizePathForSearch(path string) string {
 85→	// Same logic as claudecode.SanitizePathForClaude — replace non-alphanumeric with dash.
 86→	result := make([]byte, len(path))
 87→	for i := range len(path) {
 88→		c := path[i]
 89→		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') {
 90→			result[i] = c
 91→		} else {
 92→			result[i] = '-'
 93→		}
 94→	}
 95→	return string(result)
 96→}
 97→
 98→// hasPathPrefix checks if name starts with prefix followed by a dash (subdirectory separator).
 99→func hasPathPrefix(name, prefix string) bool {
100→	return len(name) > len(prefix) && name[:len(prefix)] == prefix && name[len(prefix)] == '-'
101→}
