103→// AgentTranscriptPath returns the path to a subagent's transcript file.
104→// Subagent transcripts are stored as agent-{agentId}.jsonl in the same directory
105→// as the main transcript.
106→func AgentTranscriptPath(transcriptDir, agentID string) string {
107→	return filepath.Join(transcriptDir, fmt.Sprintf("agent-%s.jsonl", agentID))
108→}
