110→// toolResultBlock represents a tool_result in a user message
111→type toolResultBlock struct {
112→	Type      string `json:"type"`
113→	ToolUseID string `json:"tool_use_id"`
114→}
115→
116→// userMessageWithToolResults represents a user message that may contain tool results
117→type userMessageWithToolResults struct {
118→	Content []toolResultBlock `json:"content"`
119→}
120→
121→// FindCheckpointUUID finds the UUID of the message containing the tool_result
122→// for the given tool_use_id. This is used to find the checkpoint point for
123→// transcript truncation when rewinding to a task.
124→// Returns the UUID and true if found, empty string and false otherwise.
125→func FindCheckpointUUID(transcript []transcriptLine, toolUseID string) (string, bool) {
126→	for _, line := range transcript {
127→		if line.Type != transcriptTypeUser {
128→			continue
129→		}
130→
131→		var msg userMessageWithToolResults
132→		if err := json.Unmarshal(line.Message, &msg); err != nil {
133→			continue
134→		}
135→
136→		for _, block := range msg.Content {
137→			if block.Type == "tool_result" && block.ToolUseID == toolUseID {
138→				return line.UUID, true
139→			}
140→		}
141→	}
142→	return "", false
143→}
144→
145→// TruncateTranscriptAtUUID returns transcript lines up to and including the
146→// line with the given UUID. If the UUID is not found or is empty, returns
147→// the entire transcript.
148→//
149→//nolint:revive // Exported for testing purposes
150→func TruncateTranscriptAtUUID(transcript []transcriptLine, uuid string) []transcriptLine {
151→	if uuid == "" {
152→		return transcript
153→	}
154→
155→	for i, line := range transcript {
156→		if line.UUID == uuid {
157→			return transcript[:i+1]
158→		}
159→	}
160→
161→	// UUID not found, return full transcript
162→	return transcript
163→}
