189→// TranscriptPosition contains the position information for a transcript file.
190→type TranscriptPosition struct {
191→	LastUUID  string // Last non-empty UUID (from user/assistant messages)
192→	LineCount int    // Total number of lines
193→}
194→
195→// GetTranscriptPosition reads a transcript file and returns the last UUID and line count.
196→// Returns empty position if file doesn't exist or is empty.
197→// Only considers UUIDs from actual messages (user/assistant), not summary rows which use leafUuid.
198→func GetTranscriptPosition(path string) (TranscriptPosition, error) {
199→	if path == "" {
200→		return TranscriptPosition{}, nil
201→	}
202→
203→	file, err := os.Open(path) //nolint:gosec // Reading from controlled transcript path
204→	if err != nil {
205→		if os.IsNotExist(err) {
206→			return TranscriptPosition{}, nil
207→		}
208→		return TranscriptPosition{}, fmt.Errorf("failed to open transcript: %w", err)
209→	}
210→	defer func() { _ = file.Close() }()
211→
212→	var pos TranscriptPosition
213→	reader := bufio.NewReader(file)
214→
215→	for {
216→		lineBytes, err := reader.ReadBytes('\n')
217→		if err != nil && err != io.EOF {
218→			return TranscriptPosition{}, fmt.Errorf("failed to read transcript: %w", err)
219→		}
220→
221→		if len(lineBytes) == 0 {
222→			if err == io.EOF {
223→				break
224→			}
225→			continue
226→		}
227→
228→		pos.LineCount++
229→
230→		// Parse line to extract UUID (only from user/assistant messages, not summaries)
231→		var line transcriptLine
