// searchTranscriptInAllProjects searches for a session transcript across all agent
// project directories. This handles cases where the session was started from a
// different directory than the current repo root — Claude Code uses cwd for its
// project directory, so sessions started from subdirectories, parent directories,
// or entirely different paths are stored under different project directory names.
func searchTranscriptInAllProjects(ctx context.Context, sessionID string, agent agentpkg.Agent) (string, error) {
	homeDir, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("failed to get home directory: %w", err)
	}

	projectsDir := filepath.Join(homeDir, ".claude", "projects")
	entries, err := os.ReadDir(projectsDir)
	if err != nil {
		return "", fmt.Errorf("failed to read projects directory: %w", err)
	}

	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		candidate := agent.ResolveSessionFile(filepath.Join(projectsDir, entry.Name()), sessionID)
		if _, statErr := os.Stat(candidate); statErr == nil {
			return candidate, nil
		}
	}

	return "", errors.New("transcript not found in any project directory")
}

