// sanitizePathForSearch converts a path the same way Claude Code does for project directories.
func sanitizePathForSearch(path string) string {
	// Same logic as claudecode.SanitizePathForClaude — replace non-alphanumeric with dash.
	result := make([]byte, len(path))
	for i := range len(path) {
		c := path[i]
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') {
			result[i] = c
		} else {
			result[i] = '-'
		}
	}
	return string(result)
}

// hasPathPrefix checks if name starts with prefix followed by a dash (subdirectory separator).
func hasPathPrefix(name, prefix string) bool {
	return len(name) > len(prefix) && name[:len(prefix)] == prefix && name[len(prefix)] == '-'
}

