 23→// resolveTranscriptPath determines the correct file path for an agent's session transcript.
 24→// Computes the path dynamically from the current repo location for cross-machine portability.
 25→func resolveTranscriptPath(ctx context.Context, sessionID string, agent agentpkg.Agent) (string, error) {
 26→	repoRoot, err := paths.WorktreeRoot(ctx)
 27→	if err != nil {
 28→		return "", fmt.Errorf("failed to get worktree root: %w", err)
 29→	}
 30→
 31→	sessionDir, err := agent.GetSessionDir(repoRoot)
 32→	if err != nil {
 33→		return "", fmt.Errorf("failed to get agent session directory: %w", err)
 34→	}
 35→	return agent.ResolveSessionFile(sessionDir, sessionID), nil
 36→}
