 38→// searchTranscriptInAllProjects searches for a session transcript across all agent
 39→// project directories. This handles cases where the session was started from a
 40→// different directory than the current repo root — Claude Code uses cwd for its
 41→// project directory, so sessions started from subdirectories, parent directories,
 42→// or entirely different paths are stored under different project directory names.
 43→func searchTranscriptInAllProjects(_ context.Context, sessionID string, agent agentpkg.Agent) (string, error) {
 44→	homeDir, err := os.UserHomeDir()
 45→	if err != nil {
 46→		return "", fmt.Errorf("failed to get home directory: %w", err)
 47→	}
 48→
 49→	projectsDir := filepath.Join(homeDir, ".claude", "projects")
 50→	entries, err := os.ReadDir(projectsDir)
 51→	if err != nil {
 52→		return "", fmt.Errorf("failed to read projects directory: %w", err)
 53→	}
 54→
 55→	for _, entry := range entries {
 56→		if !entry.IsDir() {
 57→			continue
 58→		}
 59→		candidate := agent.ResolveSessionFile(filepath.Join(projectsDir, entry.Name()), sessionID)
 60→		if _, statErr := os.Stat(candidate); statErr == nil {
 61→			return candidate, nil
 62→		}
 63→	}
 64→
 65→	return "", errors.New("transcript not found in any project directory")
 66→}
