 75→// toolResultBlock represents a tool_result in a user message
 76→type toolResultBlock struct {
 77→	Type      string `json:"type"`
 78→	ToolUseID string `json:"tool_use_id"`
 79→}
 80→
 81→// userMessageWithToolResults represents a user message that may contain tool results
 82→type userMessageWithToolResults struct {
 83→	Content []toolResultBlock `json:"content"`
