 85→
 86→// FindCheckpointUUID finds the UUID of the message containing the tool_result
 87→// for the given tool_use_id. This is used to find the checkpoint point for
 88→// transcript truncation when rewinding to a task.
 89→// Returns the UUID and true if found, empty string and false otherwise.
 90→func FindCheckpointUUID(transcript []transcriptLine, toolUseID string) (string, bool) {
 91→	for _, line := range transcript {
 92→		if line.Type != transcriptTypeUser {
 93→			continue
 94→		}
 95→
 96→		var msg userMessageWithToolResults
 97→		if err := json.Unmarshal(line.Message, &msg); err != nil {
 98→			continue
 99→		}
100→
101→		for _, block := range msg.Content {
102→			if block.Type == "tool_result" && block.ToolUseID == toolUseID {
103→				return line.UUID, true
104→			}
105→		}
106→	}
107→	return "", false
108→}
