110→// TruncateTranscriptAtUUID returns transcript lines up to and including the
111→// line with the given UUID. If the UUID is not found or is empty, returns
112→// the entire transcript.
113→//
114→//nolint:revive // Exported for testing purposes
115→func TruncateTranscriptAtUUID(transcript []transcriptLine, uuid string) []transcriptLine {
116→	if uuid == "" {
117→		return transcript
118→	}
119→
120→	for i, line := range transcript {
121→		if line.UUID == uuid {
122→			return transcript[:i+1]
123→		}
124→	}
125→
126→	// UUID not found, return full transcript
127→	return transcript
128→}
