130→// writeTranscript writes transcript lines to a file in JSONL format.
131→func writeTranscript(path string, transcript []transcriptLine) error {
132→	file, err := os.Create(path) //nolint:gosec // Writing to controlled git metadata path
133→	if err != nil {
134→		return fmt.Errorf("failed to create file: %w", err)
135→	}
136→	defer func() { _ = file.Close() }()
137→
138→	for _, line := range transcript {
139→		data, err := json.Marshal(line)
140→		if err != nil {
141→			return fmt.Errorf("failed to marshal line: %w", err)
142→		}
143→		if _, err := file.Write(data); err != nil {
144→			return fmt.Errorf("failed to write line: %w", err)
145→		}
146→		if _, err := file.WriteString("\n"); err != nil {
147→			return fmt.Errorf("failed to write newline: %w", err)
148→		}
149→	}
150→
151→	return nil
152→}
