154→// TranscriptPosition contains the position information for a transcript file.
155→type TranscriptPosition struct {
156→	LastUUID  string // Last non-empty UUID (from user/assistant messages)
157→	LineCount int    // Total number of lines
158→}
159→
160→// GetTranscriptPosition reads a transcript file and returns the last UUID and line count.
161→// Returns empty position if file doesn't exist or is empty.
162→// Only considers UUIDs from actual messages (user/assistant), not summary rows which use leafUuid.
163→func GetTranscriptPosition(path string) (TranscriptPosition, error) {
164→	if path == "" {
165→		return TranscriptPosition{}, nil
166→	}
167→
168→	file, err := os.Open(path) //nolint:gosec // Reading from controlled transcript path
169→	if err != nil {
170→		if os.IsNotExist(err) {
171→			return TranscriptPosition{}, nil
172→		}
173→		return TranscriptPosition{}, fmt.Errorf("failed to open transcript: %w", err)
174→	}
175→	defer func() { _ = file.Close() }()
176→
177→	var pos TranscriptPosition
178→	reader := bufio.NewReader(file)
179→
180→	for {
181→		lineBytes, err := reader.ReadBytes('\n')
182→		if err != nil && err != io.EOF {
183→			return TranscriptPosition{}, fmt.Errorf("failed to read transcript: %w", err)
184→		}
185→
186→		if len(lineBytes) == 0 {
187→			if err == io.EOF {
188→				break
189→			}
190→			continue
191→		}
192→
193→		pos.LineCount++
194→
195→		// Parse line to extract UUID (only from user/assistant messages, not summaries)
196→		var line transcriptLine
197→		if err := json.Unmarshal(lineBytes, &line); err == nil {
198→			if line.UUID != "" {
199→				pos.LastUUID = line.UUID
200→			}
201→		}
202→
203→		if err == io.EOF {
204→			break
205→		}
206→	}
207→
208→	return pos, nil
209→}
