// searchTranscriptInClaudeProjects searches for a session transcript across all Claude Code
// project directories. Claude Code uses the cwd-based project directory, so the transcript
// may be stored under any project directory name if the session was started from a different
// working directory than the current repo root.
func searchTranscriptInClaudeProjects(sessionID string, agent agentpkg.Agent) (string, error) {
	homeDir, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("failed to get home directory: %w", err)
	}

	projectsDir := filepath.Join(homeDir, ".claude", "projects")
	entries, err := os.ReadDir(projectsDir)
	if err != nil {
		return "", fmt.Errorf("failed to read projects directory: %w", err)
	}

	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		candidate := agent.ResolveSessionFile(filepath.Join(projectsDir, entry.Name()), sessionID)
		if _, statErr := os.Stat(candidate); statErr == nil {
			return candidate, nil
		}
	}

	return "", errors.New("transcript not found in any project directory")
}

